// Shared contracts. Every module builds against this file; nothing here has behaviour.
// If you are implementing a module and need a change here, do NOT edit this file:
// describe the change in your final report and work around it locally.

import type { Doc, DocMeta } from './tree.ts';

// ───────────────────────────── page model ─────────────────────────────

/** wire = plain HTTP, no JS · ghost = JS + DOM, no pixels, virtual time · chrome = real Chromium over CDP */
export type Tier = 'wire' | 'ghost' | 'chrome';

export type Region = 'dialog' | 'main' | 'other' | 'header' | 'nav' | 'aside' | 'footer' | 'cookie';

export type ActKind =
  | 'link' // navigates to href
  | 'button' // submit button (form/fi set) or script-driven button (js set)
  | 'input' // text-like input (type holds the HTML input type)
  | 'textarea'
  | 'select'
  | 'check'
  | 'radio'
  | 'file'
  | 'click'; // non-native clickable (div onclick, cursor:pointer, role=tab ...)

/** An actionable element, inline in a block. JSON-serialisable. */
export interface Act {
  /** fingerprint: stable identity of this element across re-renders of the page */
  f: string;
  k: ActKind;
  /** label shown to the agent */
  l: string;
  /** absolute URL, for links */
  href?: string;
  /** index into Page.forms and into that form's fields (wire tier form model) */
  form?: number;
  fi?: number;
  /** HTML input type, when not plain text */
  type?: string;
  /** current value (inputs, textarea, select = selected option label) */
  val?: string;
  /** checked (check/radio) or pressed/selected/expanded for stateful clickables */
  on?: boolean;
  /** option labels for selects (capped) */
  opts?: string[];
  dis?: boolean;
  /** other names the control answers to: placeholder, aria-label, title (when not the label) */
  al?: string[];
  /** needs a script-capable engine: acting on it from the wire tier triggers escalation */
  js?: boolean;
  /** live node id in a stateful engine; never persisted across engine eviction */
  n?: number;
}

export type Inline = string | Act;

export type BlockKind =
  | 'h' // heading (lv = level 1..6)
  | 'p' // paragraph / generic line
  | 'li' // list item (lv = nesting depth, ord = ordinal for ordered lists)
  | 'row' // table row or folded record (g = group id, hd = header row)
  | 'pre' // preformatted / code
  | 'q'; // blockquote line

export interface Block {
  k: BlockKind;
  r: Region;
  i: Inline[];
  lv?: number;
  ord?: number;
  /** group id: rows of the same table / items of the same list / records of the same fold */
  g?: number;
  /** index of the enclosing form in Page.forms */
  fm?: number;
  hd?: boolean;
  /** the text reads like instructions aimed at an AI agent (prompt injection); rendered with a ⚠ */
  sus?: 1;
  /** content hash (text + control state). Equal hash = the agent has seen exactly this line. */
  hx: string;
}

export interface Field {
  name: string;
  /** input type, or "select" | "textarea" | "submit" | "button" */
  type: string;
  value: string;
  checked?: boolean;
  options?: { l: string; v: string; s?: boolean }[];
  multiple?: boolean;
  disabled?: boolean;
  label?: string;
}

export interface FormDef {
  /** stable key: method + action path + ordinal */
  key: string;
  /** absolute action URL */
  action: string;
  method: 'GET' | 'POST';
  enctype: string;
  fields: Field[];
  /** true when the form has no action and/or is clearly script-driven */
  js?: boolean;
}

export type PageKind = 'html' | 'json' | 'text' | 'markdown' | 'feed' | 'csv' | 'pdf' | 'binary';

export interface Page {
  url: string;
  status: number;
  title: string;
  tier: Tier;
  kind: PageKind;
  /** how the document was requested. Only GET pages may be re-opened in another tier. */
  method: 'GET' | 'POST';
  blocks: Block[];
  forms: FormDef[];
  notes: string[];
  stats: { bytes: number; ms: number; hidden: number; scripts: number; words: number; acts: number };
  /** the document looks like an empty JS shell */
  shell?: boolean;
  meta?: Pick<DocMeta, 'description' | 'lang' | 'links'>;
}

// ───────────────────────────── engines ─────────────────────────────

export interface NavRequest {
  url: string;
  method?: 'GET' | 'POST';
  body?: string | Uint8Array;
  contentType?: string;
  referer?: string;
  /** read intent: the engine may negotiate text/markdown and may serve from the shared cache */
  read?: boolean;
  headers?: Record<string, string>;
}

export interface Loaded {
  /** final URL after redirects */
  url: string;
  status: number;
  method: 'GET' | 'POST';
  /** lower-case mime type without parameters */
  contentType: string;
  /** HTML documents */
  doc?: Doc;
  /** anything that is not HTML: handed to a Reader */
  body?: { text?: string; bytes?: Uint8Array };
  bytes: number;
  ms: number;
  cached?: boolean;
  /** things worth telling the agent: JS dialogs, console errors, downloads, blocked popups */
  events?: string[];
  /** set when the engine believes the page did not work at this tier (reason) */
  escalate?: string;
  /** screenshot result */
  image?: { mime: string; data: string };
  /** response headers the runtime may care about (lower-case names) */
  headers?: Record<string, string>;
}

export type Action =
  | { do: 'click'; n: number }
  | { do: 'fill'; n: number; value: string }
  | { do: 'select'; n: number; value: string }
  | { do: 'check'; n: number; on: boolean }
  | { do: 'press'; key: string; n?: number }
  | { do: 'hover'; n: number }
  | { do: 'scroll'; to: 'bottom' | 'top' | number }
  | { do: 'wait'; ms?: number; text?: string }
  | { do: 'back' }
  | { do: 'shot'; full?: boolean; n?: number }
  | { do: 'upload'; n: number; files: { name: string; mime: string; data: string }[] };

export interface CookieData {
  name: string;
  value: string;
  domain: string;
  path: string;
  /** epoch seconds; absent = session cookie */
  expires?: number;
  secure?: boolean;
  httpOnly?: boolean;
  sameSite?: 'Strict' | 'Lax' | 'None';
  hostOnly?: boolean;
}

export interface CookieJar {
  /** value for the Cookie request header ('' if none) */
  header(url: string): string;
  /** apply Set-Cookie header values received from `url` */
  setFromHeaders(url: string, setCookie: string[]): void;
  all(): CookieData[];
  set(c: CookieData): void;
  /** upsert cookies read back from a browser engine */
  merge(cookies: CookieData[]): void;
  /** true if any cookie would be sent to this URL (used for "is this session authenticated here") */
  has(url: string): boolean;
  clear(): void;
}

/** Everything an engine needs to know about the session it is serving. */
export interface SessionCtx {
  id: string;
  jar: CookieJar;
  /** origin -> localStorage snapshot. Stateful engines keep it current so eviction loses only JS heap. */
  storage: Record<string, Record<string, string>>;
  userAgent: string;
  guard: Guard;
  timeoutMs: number;
  signal?: AbortSignal;
  /** URL the session is on, so a stateful engine can rehydrate after eviction */
  url?: string;
}

export interface Engine {
  readonly tier: Tier;
  /** can this engine be used in this process (binary found, dependency present)? */
  available(): Promise<boolean>;
  open(ctx: SessionCtx, req: NavRequest): Promise<Loaded>;
  /** stateful tiers only: perform one action on the live page, settle, return the new document */
  act?(ctx: SessionCtx, action: Action): Promise<Loaded>;
  /** stateful tiers only: re-read the live page */
  snapshot?(ctx: SessionCtx): Promise<Loaded>;
  /** does a live page exist for this session right now? */
  live?(sessionId: string): boolean;
  /** drop live resources for the session; the session record is unaffected */
  release(sessionId: string): Promise<void>;
  close(): Promise<void>;
  stats?(): Record<string, number>;
}

export type ErrCode =
  | 'stale' // live node id no longer exists: re-snapshot and re-resolve
  | 'timeout'
  | 'net' // DNS / connect / TLS / protocol failure
  | 'blocked' // bot wall, 403, captcha
  | 'policy' // refused by Guard
  | 'unsupported' // this tier cannot do that
  | 'gone' // no live page for the session
  | 'bad_request'
  | 'too_large'
  | 'internal';

export class AwError extends Error {
  code: ErrCode;
  /** optional hint shown to the agent */
  hint?: string;
  constructor(code: ErrCode, message: string, hint?: string) {
    super(message);
    this.name = 'AwError';
    this.code = code;
    this.hint = hint;
  }
}

// ───────────────────────────── guard ─────────────────────────────

export type Verdict = { ok: true; warn?: string } | { ok: false; reason: string };

export interface StepInfo {
  verb: string;
  /** origin of the page the step acts on */
  origin?: string;
  /** destination URL for navigations and submits */
  dest?: string;
  method?: 'GET' | 'POST';
  /** label of the control acted on */
  label?: string;
  /** agent-supplied text (fill values, urls) */
  text?: string;
}

export interface Guard {
  /** SSRF + allow/deny lists. Engines call this for the navigation URL and every redirect hop. */
  checkUrl(url: string, why: 'open' | 'redirect' | 'sub' | 'submit'): Promise<Verdict>;
  /** called by the runtime before each mutating step */
  checkStep(info: StepInfo): Promise<Verdict>;
  /** replace {{secret:name}} handles for a destination origin; throws AwError('policy') if not allowed there */
  reveal(text: string, origin: string): string;
  /** scrub secret values from text returned to the model */
  redact(text: string): string;
  /** record content shown to the agent, for data-flow tracking */
  observe(origin: string, text: string, authed: boolean): void;
  /** check agent-supplied text about to leave for `origin` */
  checkOutflow(text: string, origin: string): Verdict;
  /** serialisable state persisted with the session */
  state(): unknown;
}

// ───────────────────────────── storage ─────────────────────────────

/** Namespaced key-value store of JSON values. All state that must survive a worker lives here. */
export interface Store {
  get<T = unknown>(ns: string, key: string): Promise<T | undefined>;
  set<T = unknown>(ns: string, key: string, value: T, ttlSec?: number): Promise<void>;
  del(ns: string, key: string): Promise<void>;
  /** keys in a namespace (for inspection / tests; may be capped) */
  keys(ns: string, prefix?: string, limit?: number): Promise<string[]>;
  close(): Promise<void>;
  /** approximate counters for metrics */
  stats?(): Record<string, number>;
}

// ───────────────────────────── readers ─────────────────────────────

export interface ReadInput {
  url: string;
  contentType: string;
  text?: string;
  bytes?: Uint8Array;
}

export interface ReadOutput {
  title: string;
  kind: PageKind;
  blocks: Block[];
  notes?: string[];
}

// ───────────────────────────── search ─────────────────────────────

export interface SearchResult {
  title: string;
  url: string;
  snippet: string;
  /** provider that returned it */
  source: string;
}

/** A plain fetch through the wire engine (cookies, guard, cache, politeness all applied). */
export type Fetcher = (req: NavRequest) => Promise<Loaded>;

export interface SearchProvider {
  name: string;
  available(): boolean;
  search(q: string, opts: { n: number; fetch: Fetcher }): Promise<SearchResult[]>;
}

// ───────────────────────────── atlas ─────────────────────────────

/** What the fleet has learned about one origin. Only server-derived facts; never agent-authored text. */
export interface SiteInfo {
  origin: string;
  /** cheapest tier known to work, with a 0..1 confidence */
  tier?: Tier;
  tierConf?: number;
  /** site search URL template containing {q} */
  search?: string;
  /** honours Accept: text/markdown */
  md?: boolean;
  feeds?: string[];
  updated: number;
}

export type AtlasEvent =
  | { type: 'load'; origin: string; url: string; tier: Tier; ok: boolean; shell: boolean; ms: number }
  | { type: 'forms'; origin: string; url: string; forms: FormDef[] }
  | { type: 'meta'; origin: string; url: string; links: DocMeta['links']; markdown: boolean };

export interface Atlas {
  site(origin: string): Promise<SiteInfo | undefined>;
  /** fire-and-forget learning; must never throw */
  observe(ev: AtlasEvent): void;
  flush(): Promise<void>;
}

// ───────────────────────────── runtime ─────────────────────────────

export interface RunOptions {
  /** max tokens of output for this call */
  budget?: number;
  /** tenant / API key namespace (hosted mode) */
  tenant?: string;
  /** create the session as a copy of this one if it does not exist yet */
  fork?: string;
  signal?: AbortSignal;
}

export interface RunStats {
  steps: number;
  ms: number;
  /** estimated tokens in `text` */
  tokens: number;
  tier?: Tier;
  url?: string;
  /** network fetches performed */
  fetches: number;
}

export interface RunResult {
  ok: boolean;
  text: string;
  images?: { mime: string; data: string }[];
  stats: RunStats;
}

export interface RunEvent {
  at: number;
  session: string;
  tenant?: string;
  program: string;
  ok: boolean;
  stats: RunStats;
  /** first lines of the output, for the inspector */
  preview: string;
}

export interface ToolSpec {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
}

export interface Runtime {
  run(session: string, program: string, opts?: RunOptions): Promise<RunResult>;
  /** the single tool every surface (MCP, REST, CLI) exposes */
  tool(): ToolSpec;
  /** subscribe to run events (inspector UI, metrics); returns an unsubscribe function */
  subscribe(fn: (e: RunEvent) => void): () => void;
  metrics(): Record<string, number>;
  close(): Promise<void>;
}

export type { Doc, DocMeta };
